import Foundation

/// Extracts complete fields from the JSON generated by a streaming response.
struct TranslationStream {
    private var text = ""
    private var completed = false

    mutating func receive(_ line: String) throws -> TranslationResult? {
        guard line.hasPrefix("data: ") else { return nil }
        let data = Data(line.dropFirst(6).utf8)
        guard let event = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let type = event["type"] as? String else { return nil }
        if type == "response.failed" || type == "response.incomplete" || type == "error" { throw RealtimeServiceError.upstream }
        if type == "response.completed" { completed = true; return nil }
        guard type == "response.output_text.delta", let delta = event["delta"] as? String else { return nil }
        text += delta
        guard let german = field("german") as? String, let other = field("other") as? String else { return nil }
        let object: [String: Any] = ["german": german, "other": other,
                                     "note": field("note") as? String ?? "",
                                     "words": field("words") as? [[String: Any]] ?? [],
                                     "tones": field("tones") as? [[String: Any]] ?? [],
                                     "examples": field("examples") as? [[String: Any]] ?? []]
        // Include only fully generated sections. Decoding checks every item.
        let partialData = try JSONSerialization.data(withJSONObject: object)
        return TranslationResult(try JSONDecoder().decode(ServerTranslation.self, from: partialData))
    }

    func finish() throws -> TranslationResult {
        guard completed, let data = text.data(using: .utf8) else { throw RealtimeServiceError.upstream }
        return TranslationResult(try JSONDecoder().decode(ServerTranslation.self, from: data))
    }

    // swiftlint:disable:next cyclomatic_complexity
    private func field(_ key: String) -> Any? {
        guard let range = text.range(of: "\"\(key)\"\\s*:", options: .regularExpression) else { return nil }
        var index = range.upperBound
        while index < text.endIndex, text[index].isWhitespace { index = text.index(after: index) }
        guard index < text.endIndex else { return nil }
        let start = index
        var depth = 0
        var inString = false
        var escaped = false
        while index < text.endIndex {
            let character = text[index]
            if inString {
                if escaped { escaped = false } else if character == "\\" { escaped = true } else if character == "\"" { inString = false }
            } else {
                if character == "\"" { inString = true } else if character == "[" || character == "{" { depth += 1
                } else if character == "]" || character == "}" { depth -= 1 }
            }
            let next = text.index(after: index)
            if !inString && depth == 0 {
                let fragment = Data(text[start..<next].utf8)
                if let value = try? JSONSerialization.jsonObject(with: fragment, options: .fragmentsAllowed) { return value }
            }
            index = next
        }
        return nil
    }
}
